def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            typ, _ = peek()
            if typ == '+':
                advance()
                rhs = parse_term()
                val = val + rhs
            elif typ == '-':
                advance()
                rhs = parse_term()
                val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            typ, _ = peek()
            if typ == '*':
                advance()
                rhs = parse_factor()
                val = val * rhs
            elif typ == '/':
                advance()
                rhs = parse_factor()
                # truncate toward zero
                sign = 1
                a, b = val, rhs
                if (a < 0) != (b < 0):
                    sign = -1
                q = abs(a) // abs(b)
                val = sign * q
            else:
                break
        return val

    def parse_factor():
        typ, _ = peek()
        if typ == '-':
            advance()
            return -parse_factor()
        return parse_atom()

    def parse_atom():
        typ, val = peek()
        if typ == 'NUM':
            advance()
            return val
        if typ == '(':
            advance()
            v = parse_expr()
            typ2, _ = peek()
            if typ2 != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return v
        raise ValueError(f"Unexpected token: {typ}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

